begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_function('public','read_my_push_registration_intent',array['uuid','uuid','text','text','text','text','text'],'registration snapshot RPC exists');
select has_function('public','register_my_push_token',array['uuid','uuid','text','text','text','text','text','text','text','text','text','text','jsonb','uuid','uuid','text'],'versioned registration RPC exists');
select ok(not has_function_privilege('authenticated','public.wave1_register_push_token(uuid,uuid,text,text,text,text,text,text,text,text,text,text,jsonb)','EXECUTE'),'authenticated legacy unfenced register is closed');
select ok(not has_function_privilege('anon','public.read_my_push_registration_intent(uuid,uuid,text,text,text,text,text)','EXECUTE'),'anonymous capture is denied');
select ok(not has_function_privilege('service_role','public.register_my_push_token(uuid,uuid,text,text,text,text,text,text,text,text,text,text,jsonb,uuid,uuid,text)','EXECUTE'),'service cannot impersonate caller-bound registration');
select ok(has_function_privilege('service_role','public.wave1_revoke_push_ownership(uuid,uuid,text,text,text,text,text,text)','EXECUTE'),'held revoke grant is retained');
select ok(not has_table_privilege('authenticated','private.notification_registration_streams','SELECT,INSERT,UPDATE,DELETE'),'stream is not client mutable or readable');
select ok(not has_table_privilege('service_role','private.notification_registration_receipts','SELECT,INSERT,UPDATE,DELETE'),'receipts cannot be fabricated by service');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.notification_registration_streams'::regclass),'stream has forced RLS');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.notification_registration_receipts'::regclass),'receipts have forced RLS');
insert into auth.users(id,email,email_confirmed_at,is_sso_user,is_anonymous) values('8d000000-0000-4000-8000-000000000001','registration-pgtap@example.test',now(),false,false);
insert into auth.sessions(id,user_id) values('8d000000-0000-4000-8000-000000000002','8d000000-0000-4000-8000-000000000001');
create temporary table registration_results(label text primary key,result jsonb);
grant all on registration_results to authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"8d000000-0000-4000-8000-000000000001","session_id":"8d000000-0000-4000-8000-000000000002"}',true);
set local role authenticated;
insert into registration_results values('snapshot', public.read_my_push_registration_intent('8d000000-0000-4000-8000-000000000001','8d000000-0000-4000-8000-000000000001','8d000000-0000-4000-8000-000000000002','ios','expo','registration-pgtap',repeat('a',64)));
select is((select result->>'revision' from registration_results where label='snapshot'),'0','initial server stream is revision zero');
insert into registration_results select 'accepted', public.register_my_push_token('8d000000-0000-4000-8000-000000000001','8d000000-0000-4000-8000-000000000001','8d000000-0000-4000-8000-000000000002','ios','expo','registration-pgtap','ExpoPushToken[accepted]',repeat('a',64),'register:8d000000-0000-4000-8000-000000000003','granted',null,null,'{}','8d000000-0000-4000-8000-000000000003',(result->>'incarnation')::uuid,'0') from registration_results where label='snapshot';
select is((select result->>'status' from registration_results where label='accepted'),'registered','first captured registration applies');
select is((select result->>'revision' from registration_results where label='accepted'),'1','registration advances stream');
insert into registration_results select 'conflict', public.register_my_push_token('8d000000-0000-4000-8000-000000000001','8d000000-0000-4000-8000-000000000001','8d000000-0000-4000-8000-000000000002','ios','expo','registration-pgtap','ExpoPushToken[delayed]',repeat('a',64),'register:8d000000-0000-4000-8000-000000000004','granted',null,null,'{}','8d000000-0000-4000-8000-000000000004',(result->>'incarnation')::uuid,'0') from registration_results where label='snapshot';
select is((select result->>'status' from registration_results where label='conflict'),'conflict','delayed old baseline cannot overwrite');
select is((select result->>'tokenFingerprint' from registration_results where label='conflict'),(select result->>'tokenFingerprint' from registration_results where label='accepted'),'conflict reports actual current token');
reset role;
select is((select count(*)::int from private.notification_registration_receipts where actor_user_id='8d000000-0000-4000-8000-000000000001'),2,'both accepted and conflict outcomes have bound receipts');
select is((select token from public.user_push_tokens where install_id='registration-pgtap' and enabled),'ExpoPushToken[accepted]','winner remains enabled');
select * from finish();
rollback;
